function renderCategories(){let el=$('#categoryList');el.innerHTML=categories.map(c=>`<button class="category-btn ${c.id===currentCat?'active':''}" data-cat="${c.id}"><span class="category-icon">${c.icon}</span>${c.name}<span class="cat-count">${c.parts.length}</span></button>`).join('');$$('.category-btn').forEach(b=>b.onclick=()=>{currentCat=b.dataset.cat;renderCategories();renderParts()})}
function renderParts(){let cat=categories.find(c=>c.id===currentCat);$('#categoryTitle').textContent=cat.name;$('#categoryEyebrow').textContent=cat.eyebrow;$('#partsGrid').innerHTML=cat.parts.map((p,i)=>{let selected=equipped(cat.id)===i,owned=selected,locked=balance<p[2];let delta=cat.id==='engine'||cat.id==='turbo'?`+${p[4]} л.с.`:cat.id==='tires'||cat.id==='brakes'?`+${p[5]} управ.`:cat.id==='exhaust'?`+${p[4]} звук`:'АЭРО +';return `<article class="part-card ${selected?'equipped':''}"><div class="part-top"><span class="part-icon">${cat.icon}</span><span class="part-tier">${i===0?'БАЗА':i===1?'STREET':i===2?'SPORT':'RACING'}</span></div><h3>${p[0]}</h3><p>${p[1]}</p><div class="part-bottom"><span class="part-price">${p[2]===0?'ШТАТНО':'₽ '+fmt(p[2])}</span><span class="part-stats">${delta}</span><button class="part-action ${selected?'':'buy'}" data-index="${i}" ${locked&&!selected?'disabled':''}>${selected?'УСТАНОВЛЕНО':owned?'УСТАНОВИТЬ':locked?'НЕ ХВАТАЕТ':'КУПИТЬ'}</button></div></article>`}).join('');$$('.part-action').forEach(b=>b.onclick=()=>buyPart(cat,Number(b.dataset.index)))}
function buyPart(cat,index){if(purchaseBusy||equipped(cat.id)===index)return;let p=cat.parts[index];if(balance<p[2]){toast('Не хватает денег — заработай в гонке');return}if(p[2]){balance-=p[2];setBalance()}purchaseBusy=true;let box=document.createElement('div');box.className='upgrade-overlay';box.innerHTML=`<div class="upgrade-box"><div class="upgrade-icon">${cat.icon}</div><span class="eyebrow">REDLINE CUSTOM WORKS</span><h2>${cat.id==='engine'?'ЗАМЕНА ДВИГАТЕЛЯ':cat.id==='turbo'?'УСТАНОВКА ТУРБО':cat.id==='body'?'АЭРОДИНАМИКА':`УСТАНОВКА: ${cat.name.toUpperCase()}`}</h2><p>${cat.id==='engine'?'Капот открыт · старый мотор снят · готовим новый блок':cat.id==='turbo'?'Снимаем впуск · ставим турбину · настраиваем буст':'Снимаем старую деталь · подгоняем крепления · проверяем'}</p><div class="upgrade-progress"><i></i></div><span class="upgrade-step" id="upgradeStep">ОТКРЫВАЕМ КАПОТ</span></div>`;document.body.appendChild(box);let steps=['ОТКРЫВАЕМ КАПОТ','СНИМАЕМ СТАРУЮ ДЕТАЛЬ','УСТАНАВЛИВАЕМ НОВУЮ','ПРОВЕРКА И НАСТРОЙКА'];let n=0;let interval=setInterval(()=>{$('#upgradeStep').textContent=steps[Math.min(++n,3)]},590);requestAnimationFrame(()=>box.querySelector('.upgrade-progress i').style.width='100%');setTimeout(()=>{clearInterval(interval);chosen[carIndex][cat.id]=index;localStorage.setItem('redlineParts',JSON.stringify(chosen));box.remove();purchaseBusy=false;renderParts();refreshGarage();playRev(true)},2500)}
function toast(msg){let t=$('#raceToast');if(!t)return;t.textContent=msg;t.style.opacity='1';setTimeout(()=>t.style.opacity='0',1600)}
function initAudio(){if(!soundOn)return;if(!audio){let A=window.AudioContext||window.webkitAudioContext;if(!A)return;let ctx=new A(),master=ctx.createGain();master.gain.value=.22;master.connect(ctx.destination);let osc=ctx.createOscillator(),osc2=ctx.createOscillator(),gain=ctx.createGain(),g2=ctx.createGain();osc.type='sawtooth';osc2.type='triangle';osc.frequency.value=50;osc2.frequency.value=25;gain.gain.value=0;g2.gain.value=0;osc.connect(gain);osc2.connect(g2);gain.connect(master);g2.connect(master);osc.start();osc2.start();audio={ctx,master,osc,osc2,gain,g2}}if(audio.ctx.state==='suspended')audio.ctx.resume()}
function playRev(loud=false){initAudio();if(!audio)return;let {ctx,osc,osc2,gain,g2}=audio,s=stats(),now=ctx.currentTime;osc.frequency.setTargetAtTime(58+Math.min(s.power,850)/13,now,.08);osc2.frequency.setTargetAtTime(29+Math.min(s.power,850)/24,now,.08);gain.gain.cancelScheduledValues(now);g2.gain.cancelScheduledValues(now);gain.gain.setTargetAtTime(loud?.19:.12,now,.03);g2.gain.setTargetAtTime(loud?.08:.05,now,.03);gain.gain.setTargetAtTime(0,now+.65,.3);g2.gain.setTargetAtTime(0,now+.65,.3)}
function soundShift(){if(!soundOn)return;initAudio();if(!audio)return;let c=audio.ctx,o=c.createOscillator(),g=c.createGain();o.type='sawtooth';o.frequency.setValueAtTime(760,c.currentTime);o.frequency.exponentialRampToValueAtTime(230,c.currentTime+.17);g.gain.setValueAtTime(.055,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.2);o.connect(g);g.connect(audio.master);o.start();o.stop(c.currentTime+.22);playTurbo()}
function playTurbo(){if(!soundOn||!audio||equipped('turbo')<1)return;let c=audio.ctx;for(let i=0;i<5;i++){let o=c.createOscillator(),g=c.createGain(),t=c.currentTime+i*.07;o.type='sawtooth';o.frequency.setValueAtTime(150+Math.random()*40,t);o.frequency.exponentialRampToValueAtTime(55,t+.045);g.gain.setValueAtTime(.035,t);g.gain.exponentialRampToValueAtTime(.001,t+.06);o.connect(g);g.connect(audio.master);o.start(t);o.stop(t+.07)}}
function resizeRace(){let c=$('#raceCanvas');let z=resizeCanvas(c);if(z)drawRoad(z.ctx,z.w,z.h,performance.now()/900)}
